"""Parent-only extra awards, durable retry and catalogue status separation."""
import asyncio,json
from playwright.async_api import async_playwright
async def main():
 async with async_playwright() as p:
  b=await p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox']);pc=await b.new_context();cc=await b.new_context(viewport={'width':810,'height':1080});parent=await pc.new_page();child=await cc.new_page();errors=[]
  for page in [parent,child]:page.on('pageerror',lambda e:errors.append(str(e)))
  parent.on('dialog',lambda d:asyncio.create_task(d.accept()));await parent.goto('http://127.0.0.1:8876');await parent.select_option('#cloudLogin [name=mode]','create');await parent.fill('#cloudLogin [name=password]','reward-parent123');await parent.fill('#cloudLogin [name=childPassword]','123456');await parent.click('#cloudLogin button');await parent.wait_for_selector('#cloudBar:visible');code=(await parent.locator('#cloudIdentity').inner_text()).split(' ')[0]
  await parent.click('[data-parent-tab=rewards]');await parent.fill('#parentRewardForm [name=reason]','主动整理房间');await parent.click('#parentRewardForm button[type=submit]');await parent.wait_for_function('!cloudBusy');assert await parent.locator('#parentRewardForm [name=reason]').input_value()=='';assert await parent.locator('#flowerBalance').inner_text()=='1';assert '主动整理房间' in await parent.locator('#parentRewardHistory').inner_text()
  # Simulate a committed operation whose response never arrived. A new operation ID
  # with the same reward identity must not grant a second flower.
  rid=await parent.evaluate("state.ledger.find(l=>l.source==='parent').id.slice(7)")
  await parent.fill('#parentRewardForm [name=reason]','主动整理房间');await parent.locator('#parentRewardForm [name=rewardId]').evaluate('(e,id)=>e.value=id',rid);await parent.evaluate("state.ledger=state.ledger.filter(l=>l.source!=='parent')");await parent.click('#parentRewardForm button[type=submit]');await parent.wait_for_function('!cloudBusy');assert await parent.locator('#flowerBalance').inner_text()=='1'
  first=await parent.locator('#manageGifts [data-toggle-gift]').first.get_attribute('data-toggle-gift');await parent.locator('#manageGifts [data-toggle-gift]').first.click();await parent.wait_for_function('!cloudBusy');assert await parent.locator('#manageGifts [data-edit-gift="'+first+'"]').count()==0
  await parent.click('[data-gift-status=inactive]');assert await parent.locator('#manageGifts [data-edit-gift="'+first+'"]').count()==1;assert await parent.locator('#manageGifts [data-toggle-gift="'+first+'"]').inner_text()=='上架';await parent.locator('#manageGifts [data-toggle-gift="'+first+'"]').click();await parent.wait_for_function('!cloudBusy');assert await parent.locator('#manageGifts [data-edit-gift="'+first+'"]').count()==0;await parent.click('[data-gift-status=active]');assert await parent.locator('#manageGifts [data-edit-gift="'+first+'"]').count()==1
  await child.goto('http://127.0.0.1:8876');await child.fill('[name=code]',code);await child.select_option('#cloudLogin [name=role]','child');await child.fill('#cloudLogin [name=password]','123456');await child.click('#cloudLogin button');await child.wait_for_selector('#cloudBar:visible');assert not await child.locator('#parentRewardForm').is_visible();assert await child.locator('#flowerBalance').inner_text()=='1';await child.click('[data-page=growth]');assert '家长奖励 · 主动整理房间' in await child.locator('#flowerLedger').inner_text()
  # Rejection leaves the reason and stable reward identity available for retry.
  await parent.fill('#parentRewardForm [name=reason]','失败保留');await parent.route('**/api/dva/operations',lambda route:route.fulfill(status=503,content_type='application/json',body='{"error":"临时不可用"}'));await parent.click('#parentRewardForm button[type=submit]');await parent.wait_for_function('!cloudBusy');assert await parent.locator('#parentRewardForm [name=reason]').input_value()=='失败保留';assert await parent.locator('#flowerBalance').inner_text()=='1';await parent.unroute('**/api/dva/operations');await parent.click('#parentRewardForm button[type=submit]');await parent.wait_for_function('!cloudBusy');assert await parent.locator('#flowerBalance').inner_text()=='2'
  await parent.screenshot(path='preview/parent-extra-reward.png',full_page=True);assert not errors,errors;print(json.dumps({'parentAward':True,'childReadOnly':True,'sharedBalanceAndReason':True,'lostResponseNoDoubleAward':True,'statusTabs':True,'retryPreservesReason':True,'errors':errors}));await b.close()
asyncio.run(main())
